"use strict";(globalThis.webpackChunktechnical_writing_portfolio=globalThis.webpackChunktechnical_writing_portfolio||[]).push([[7399],{5312(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/portfolio/docs/intro","label":"Writing portfolio","docId":"intro","unlisted":false},{"type":"category","label":"My work at Ably","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/portfolio/docs/ably/sse-documentation","label":"Server-sent events documentation","docId":"ably/sse-documentation","unlisted":false},{"type":"link","href":"/portfolio/docs/ably/webhooks-security","label":"Webhooks security documentation","docId":"ably/webhooks-security","unlisted":false},{"type":"link","href":"/portfolio/docs/ably/troubleshooting-guides","label":"Troubleshooting guides & developer support","docId":"ably/troubleshooting-guides","unlisted":false},{"type":"link","href":"/portfolio/docs/ably/developer-journey-mapping","label":"Developer journey mapping & information architecture","docId":"ably/developer-journey-mapping","unlisted":false},{"type":"link","href":"/portfolio/docs/ably/channels-pubsub-docs","label":"Channels & pub/sub documentation","docId":"ably/channels-pubsub-docs","unlisted":false},{"type":"link","href":"/portfolio/docs/ably/content-restructuring","label":"Content restructuring & information architecture","docId":"ably/content-restructuring","unlisted":false}],"href":"/portfolio/docs/ably/"},{"type":"category","label":"My time at Couchbase","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/portfolio/docs/couchbase/mobile-platform-docs","label":"Mobile platform documentation","docId":"couchbase/mobile-platform-docs","unlisted":false},{"type":"link","href":"/portfolio/docs/couchbase/cross-platform-apis","label":"Cross-platform API documentation","docId":"couchbase/cross-platform-apis","unlisted":false},{"type":"link","href":"/portfolio/docs/couchbase/repository-consolidation","label":"Repository consolidation project","docId":"couchbase/repository-consolidation","unlisted":false}],"href":"/portfolio/docs/couchbase/"},{"type":"category","label":"My work at Atlas Copco","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/portfolio/docs/atlas-copco/self-pierce-riveting","label":"Self-pierce riveting documentation","docId":"atlas-copco/self-pierce-riveting","unlisted":false},{"type":"link","href":"/portfolio/docs/atlas-copco/flow-drill-fastening","label":"Henrob tape feed riveting documentation","docId":"atlas-copco/flow-drill-fastening","unlisted":false},{"type":"link","href":"/portfolio/docs/atlas-copco/industrial-dispensing","label":"Henrob blow feed riveting documentation","docId":"atlas-copco/industrial-dispensing","unlisted":false}],"href":"/portfolio/docs/atlas-copco/"},{"type":"link","href":"/portfolio/docs/cdw/","label":"My work at CDW","docId":"cdw/index","unlisted":false}]},"docs":{"ably/channels-pubsub-docs":{"id":"ably/channels-pubsub-docs","title":"Channels & pub/sub documentation","description":"Real-time messaging centers around the concept of \\"channels\\" - but explaining this to developers coming from HTTP request/response patterns can be challenging. I rebuilt Ably\'s channels documentation to bridge this conceptual gap.","sidebar":"tutorialSidebar"},"ably/content-restructuring":{"id":"ably/content-restructuring","title":"Content restructuring & information architecture","description":"One of my most impactful contributions at Ably has been systematically restructuring their documentation architecture. This wasn\'t just moving pages around - it was rebuilding how developers discover, understand, and implement Ably\'s platform.","sidebar":"tutorialSidebar"},"ably/developer-journey-mapping":{"id":"ably/developer-journey-mapping","title":"Developer journey mapping & information architecture","description":"At Ably, I don\'t just write documentation - I architect the entire developer experience. My role involves mapping out how developers discover, evaluate, integrate, and scale with Ably\'s platform, then designing content that drives business results through each stage of that journey.","sidebar":"tutorialSidebar"},"ably/index":{"id":"ably/index","title":"My work at Ably","description":"I joined Ably in August 2023 as a Developer Educator, working on their realtime messaging platform. My focus is making complex WebSocket and database sync concepts accessible to developers.","sidebar":"tutorialSidebar"},"ably/sse-documentation":{"id":"ably/sse-documentation","title":"Server-sent events documentation","description":"When I started working on the Server-Sent Events documentation at Ably, I quickly realized this wasn\'t going to be a typical documentation project. Real-time streaming technology is inherently difficult to explain in static text, and developers needed to understand both the technical implementation and the practical troubleshooting aspects.","sidebar":"tutorialSidebar"},"ably/troubleshooting-guides":{"id":"ably/troubleshooting-guides","title":"Troubleshooting guides & developer support","description":"One of the most impactful things I\'ve done at Ably is create practical troubleshooting resources. These aren\'t generic \\"check your network connection\\" guides - they\'re specific tools that help developers debug real-time messaging issues.","sidebar":"tutorialSidebar"},"ably/webhooks-security":{"id":"ably/webhooks-security","title":"Webhooks security documentation","description":"Security documentation is notoriously difficult to get right. It\'s either too basic (\\"just use HTTPS\\") or completely overwhelming with cryptographic theory. I rewrote Ably\'s webhook security docs to be practical and actionable.","sidebar":"tutorialSidebar"},"atlas-copco/flow-drill-fastening":{"id":"atlas-copco/flow-drill-fastening","title":"Henrob tape feed riveting documentation","description":"When I started working on the Henrob tape feed riveting documentation at Atlas Copco, I knew I was dealing with something special. This wasn\'t just another joining technology - it was a servo-driven system capable of setting rivets in just 1.2 seconds for high-volume automotive production.","sidebar":"tutorialSidebar"},"atlas-copco/index":{"id":"atlas-copco/index","title":"My work at Atlas Copco","description":"I worked as a Technical Writer at Atlas Copco from 2018 to 2021, writing documentation for industrial manufacturing equipment. My job was translating complex joining and fastening technologies into guides that engineers and factory workers could actually use.","sidebar":"tutorialSidebar"},"atlas-copco/industrial-dispensing":{"id":"atlas-copco/industrial-dispensing","title":"Henrob blow feed riveting documentation","description":"The Henrob blow feed riveting system presented a unique technical writing challenge at Atlas Copco. This was energy-efficient technology - achieving just 7Wh per rivet while delivering setting forces up to 85,000 N. The engineering was impressive, but making it accessible to production teams required a completely different approach.","sidebar":"tutorialSidebar"},"atlas-copco/self-pierce-riveting":{"id":"atlas-copco/self-pierce-riveting","title":"Self-pierce riveting documentation","description":"Self-pierce riveting was my biggest documentation project at Atlas Copco. I spent two years writing guides for their SPR technology, which is how car manufacturers join aluminum body panels without welding. This is especially important for electric vehicles where every pound matters for battery range.","sidebar":"tutorialSidebar"},"cdw/index":{"id":"cdw/index","title":"My work at CDW","description":"I worked as a Technical Solutions Specialist at CDW UK from 2021 to 2022, focusing on creating technical documentation and sales materials that helped enterprise customers understand complex IT solutions. My role was translating technical specifications into business language that procurement teams and IT directors could actually use to make informed decisions.","sidebar":"tutorialSidebar"},"couchbase/cross-platform-apis":{"id":"couchbase/cross-platform-apis","title":"Cross-platform API documentation","description":"One of the biggest challenges at Couchbase was maintaining consistent API documentation across 8+ programming languages and platforms. Mobile developers expect the same database operations to work similarly whether they\'re writing Swift, Java, or JavaScript.","sidebar":"tutorialSidebar"},"couchbase/index":{"id":"couchbase/index","title":"My time at Couchbase","description":"I was Lead Technical Writer at Couchbase from 2022 to 2023, focused on their mobile database platform. The main challenge was making NoSQL databases approachable for mobile developers who were used to simpler storage solutions.","sidebar":"tutorialSidebar"},"couchbase/mobile-platform-docs":{"id":"couchbase/mobile-platform-docs","title":"Mobile platform documentation","description":"When I joined Couchbase, their mobile platform documentation was fragmented across multiple sites. Developers couldn\'t understand how Couchbase Lite, Sync Gateway, and cloud services worked together. I rebuilt it as a unified story.","sidebar":"tutorialSidebar"},"couchbase/repository-consolidation":{"id":"couchbase/repository-consolidation","title":"Repository consolidation project","description":"The biggest technical project during my time at Couchbase was consolidating 12+ fragmented documentation repositories into a single, maintainable system. This wasn\'t just about moving files - it was about creating a sustainable documentation architecture.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Writing portfolio","description":"Hey there! I\'m Francis, and I\'ve spent the last few years working with some great companies to make their documentation actually useful for developers.","sidebar":"tutorialSidebar"}}}}')}}]);